package com.smarthealth.service;
import com.smarthealth.ai.*;import com.smarthealth.exception.*;import com.smarthealth.model.*;import com.fasterxml.jackson.databind.*;import java.time.LocalDateTime;import java.util.*;
public class HeartDiseaseDetector extends HealthService implements Detector{private final AIService ai;private final AIService fallback=new RuleBasedFallbackService();private final ObjectMapper mapper=new ObjectMapper();public HeartDiseaseDetector(AIService a){super();ai=a;}@Override public HealthResult analyzeHealth(SensorData d){return analyze(d);}@Override public HealthResult analyze(SensorData d){validate(d);try{String prompt=mapper.writeValueAsString(Map.of("heartRate",d.getHeartRate(),"systolicBP",d.getSystolicBP(),"diastolicBP",d.getDiastolicBP(),"spo2",d.getSpo2(),"timestamp",String.valueOf(d.getTimestamp())));String raw;try{raw=ai.getRiskAssessment("Assess these vitals for educational purposes only. Reply ONLY JSON with riskLevel LOW|MEDIUM|HIGH, riskScore 0-100, guidance and preventionTips. Educational tool, not a medical diagnosis. Data: "+prompt);}catch(AIServiceException e){raw=fallback.getRiskAssessment(prompt);}raw=raw.replaceAll("(?s)^\\s*```(?:json)?\\s*|\\s*```\\s*$","").trim();JsonNode n=mapper.readTree(raw);return new HealthResult(HealthResult.RiskLevel.valueOf(n.path("riskLevel").asText()),n.path("riskScore").asInt(),n.path("guidance").asText()+" Educational tool, not a medical diagnosis.",mapper.convertValue(n.path("preventionTips"),mapper.getTypeFactory().constructCollectionType(List.class,String.class)),LocalDateTime.now());}catch(Exception ex){return parseFallback(d);}}private HealthResult parseFallback(SensorData d){String json=fallback.getRiskAssessment("{\"heartRate\":"+d.getHeartRate()+",\"systolicBP\":"+d.getSystolicBP()+",\"spo2\":"+d.getSpo2()+"}");try{JsonNode n=mapper.readTree(json);return new HealthResult(HealthResult.RiskLevel.valueOf(n.get("riskLevel").asText()),n.get("riskScore").asInt(),n.get("guidance").asText()+" Educational tool, not a medical diagnosis.",List.of("Follow your care plan","Discuss changes with your clinician"),LocalDateTime.now());}catch(Exception e){return new HealthResult(HealthResult.RiskLevel.MEDIUM,40,"Please repeat the measurement and contact your clinician. Educational tool, not a medical diagnosis.",List.of("Repeat the reading"),LocalDateTime.now());}}@Override public void performService(){log.info("Heart risk detector ready");}}
